<script setup lang="ts">
import { ArrowRight, LockKeyhole } from '@lucide/vue'
const route=useRoute(),email=ref(''),password=ref(''),busy=ref(false),errorMessage=ref('')
const returnTo=computed(()=>{const value=typeof route.query.redirect==='string'?route.query.redirect:'';return value.startsWith('/')&&!value.startsWith('//')?value:''})
async function resolveDestination(){const fallback=returnTo.value||'/mon-compte';try{await $fetch('/api/admin/session');return fallback.startsWith('/admin')?fallback:'/admin'}catch{/* pas du personnel admin */}try{await $fetch('/api/staff/session');return '/staff'}catch{/* pas membre de l'équipe */}return fallback}
async function login(){busy.value=true;errorMessage.value='';try{await $fetch('/api/auth/sign-in/email',{method:'POST',body:{email:email.value.trim().toLowerCase(),password:password.value,rememberMe:true}})
// Double vérification : les accès de gestion (développeur, propriétaire,
// réception, employée) confirment un code e-mail avant d'entrer dans l'espace.
try{const gate=await $fetch<{required?:boolean;verified?:boolean}>('/api/auth-otp/status');if(gate?.required&&!gate.verified){await navigateTo({path:'/connexion/verification',query:returnTo.value?{redirect:returnTo.value}:{}});return}}catch{/* statut indisponible : poursuivre la résolution classique */}
await navigateTo(await resolveDestination())}catch(error){const data=(error as {data?:{message?:string;statusMessage?:string}})?.data;errorMessage.value=data?.message||data?.statusMessage||'Connexion refusée. Vérifiez vos informations.'}finally{busy.value=false}}
useSeoMeta({title:'Connexion — Mon espace',description:'Connectez-vous à votre espace rendez-vous.',robots:'noindex,nofollow'})
</script>
<template><div class="auth-page container-narrow"><div v-reveal class="auth-card surface-card"><span class="eyebrow">Votre espace</span><h1 class="display">Retrouvez vos rendez-vous.</h1><p>Les réservations invitées restent accessibles avec le lien sécurisé reçu lors de votre réservation.</p><form @submit.prevent="login"><label class="form-field"><span>Adresse e-mail</span><input v-model="email" class="form-control" type="email" autocomplete="email" required maxlength="254"></label><label class="form-field"><span>Mot de passe</span><input v-model="password" class="form-control" type="password" autocomplete="current-password" required minlength="8"></label><button class="btn btn-primary" type="submit" :disabled="busy">{{busy?'Connexion…':'Se connecter'}} <ArrowRight :size="15"/></button><p v-if="errorMessage" class="auth-error" role="alert">{{errorMessage}}</p></form><p class="auth-secure"><LockKeyhole :size="14"/> Session protégée par Better Auth.</p><div class="auth-links"><NuxtLink to="/inscription">Créer un compte</NuxtLink><NuxtLink to="/reservation">Réserver sans compte</NuxtLink></div></div></div></template>
<style scoped>.auth-page{padding:6rem 0}.auth-card{padding:clamp(1.5rem,5vw,3rem)}.auth-card h1{margin:.8rem 0;font-size:clamp(2.8rem,6vw,4.8rem)}.auth-card>p{max-width:500px;color:var(--muted);font-size:.8rem}.auth-card form{display:grid;gap:1rem;margin-top:1.5rem}.form-field{display:grid;gap:.4rem}.form-field span{font-size:.72rem;font-weight:700}.auth-error{color:#943d48;font-size:.76rem}.auth-secure{display:flex;align-items:center;gap:.45rem;margin-top:1rem;font-size:.68rem}.auth-links{display:flex;flex-wrap:wrap;gap:1rem;border-top:1px solid var(--line);padding-top:1rem}.auth-links a{color:var(--merlot);font-size:.72rem;font-weight:700}</style>
